local module = {}
module.__index = module

local CancellationToken = require(script.Parent.PlayerScopeCancellationToken)

function module.new()
	local self = setmetatable({}, module)
	self._cancellationTokenCache = {}
	return self
end

function module:GetCancellationToken(userId: number)
	if not self._cancellationTokenCache[userId] then
		self._cancellationTokenCache[userId] = CancellationToken.new()
	end
	return self._cancellationTokenCache[userId]
end

function module:RemoveCancellationToken(userId: number)
	self._cancellationTokenCache[userId] = nil
end

return module
